#!/usr/bin/env python3
"""
Builds the Symptoms, Learn, Workplace and basket pages in Hertility's structure,
in FertiTerra branding.

Symptoms  -> eight condition pages under /blog (Hertility uses the same URLs)
Learn     -> guides, webinars, real stories, glossary
Workplace -> nine pages under /workplace
Basket    -> /cart rebuilt in Hertility's basket layout, same cart logic

Also renames the nav label Employers to Workplace and repoints the three menus.
Your existing pages are backed up, never deleted.
"""
import base64
import json
import re
from pathlib import Path

FILES = json.loads(base64.b64decode("").decode())
PAGES = json.loads(base64.b64decode("").decode())

STUB = '''import type {{ Metadata }} from "next"
import {{ SectionsPage }} from "@/components/ft/sections-page"
import {{ {comp} }} from "@/components/ft/{datafile}"

export const metadata: Metadata = {{
  title: "{title} | FertiTerra",
}}

export default function Page() {{
  return <SectionsPage entry={{{key}}} />
}}
'''

LINKS = [
    ('{ label: "Fatigue & low energy", href: "/symptoms" }', '{ label: "Fatigue & low energy", href: "/blog/fatigue-low-energy" }'),
    ('{ label: "Mood & mental health", href: "/symptoms" }', '{ label: "Mood & mental health", href: "/blog/mood-mental-health" }'),
    ('{ label: "Skin & hair changes", href: "/symptoms" }', '{ label: "Skin & hair changes", href: "/blog/skin-hair-changes" }'),
    ('{ label: "Painful & irregular cycles", href: "/symptoms" }', '{ label: "Painful & irregular cycles", href: "/blog/painful-irregular-cycles" }'),
    ('{ label: "Endometriosis", href: "/symptoms" }', '{ label: "Endometriosis", href: "/blog/endometriosis" }'),
    ('{ label: "Fibroids", href: "/symptoms" }', '{ label: "Fibroids", href: "/blog/fibroids" }'),
    ('{ label: "PMS & PMDD", href: "/symptoms" }', '{ label: "PMS & PMDD", href: "/blog/pms-pmdd" }'),
    ('{ label: "Webinars & events", href: "/blog/webinars-events" }', '{ label: "Webinars & events", href: "/learn/webinars" }'),
    ('{ label: "What we do", href: "/for-employers" }', '{ label: "What we do", href: "/workplace" }'),
    ('{ label: "Pricing", href: "/for-employers" }', '{ label: "Pricing", href: "/workplace/pricing" }'),
    ('{ label: "Our mission", href: "/about/founders-story" }', '{ label: "Our mission", href: "/workplace/mission" }'),
    ('{ label: "Contact us", href: "/screening/contact" }', '{ label: "Contact us", href: "/workplace/contact" }'),
    ('{ label: "For HR leaders", href: "/for-employers" }', '{ label: "For HR leaders", href: "/workplace/employee-benefits" }'),
    ('{ label: "For insurers", href: "/for-employers" }', '{ label: "For insurers", href: "/workplace/for-insurers" }'),
    ('{ label: "For brokers", href: "/for-employers" }', '{ label: "For brokers", href: "/workplace/for-brokers" }'),
    ('{ label: "Case studies", href: "/learn/real-stories" }', '{ label: "Case studies", href: "/workplace/case-studies" }'),
    ('{ label: "Guides and articles", href: "/learn/guides" }', '{ label: "Guides and articles", href: "/workplace/resources" }'),
]


def main():
    if not Path("package.json").is_file() or not Path("app").is_dir():
        print("Run this from the Fertiterra folder.")
        return

    print("1. Shared renderer and page content")
    for rel, content in FILES.items():
        p = Path(rel)
        p.parent.mkdir(parents=True, exist_ok=True)
        if p.is_file() and p.read_text(encoding="utf-8") == content:
            print("   already current: " + rel)
            continue
        if p.is_file() and rel == "app/cart/page.tsx":
            p.with_suffix(".tsx.bak-before-basket").write_text(p.read_text(encoding="utf-8"), encoding="utf-8")
            print("   replaced " + rel + "  (backup .bak-before-basket)")
        else:
            print("   wrote " + rel)
        p.write_text(content, encoding="utf-8")

    print("")
    print("2. The pages")
    for d, meta in PAGES.items():
        comp, key, title, datafile = meta
        p = Path(d)
        p.mkdir(parents=True, exist_ok=True)
        f = p / "page.tsx"
        body = STUB.format(comp=comp, key=key, title=title, datafile=datafile)
        if f.is_file():
            existing = f.read_text(encoding="utf-8")
            if existing == body:
                print("   already current: " + d)
                continue
            (p / "page.tsx.bak-before-rebuild").write_text(existing, encoding="utf-8")
        f.write_text(body, encoding="utf-8")
        print("   built " + d)

    print("")
    print("3. Menus")
    header = Path("components/header.tsx")
    if not header.is_file():
        print("   components/header.tsx not found, menus left alone")
    else:
        src = header.read_text(encoding="utf-8")
        original = src
        for old, new in LINKS:
            if new in src:
                print("   already set: " + new.split('href: "')[1].split('"')[0])
            elif old in src:
                src = src.replace(old, new)
                print("   repointed " + new.split('label: "')[1].split('"')[0] + " -> " + new.split('href: "')[1].split('"')[0])
            else:
                print("   NOT FOUND, left alone: " + old.split('label: "')[1].split('"')[0])

        if 'label: "Glossary"' not in src:
            m = re.search(r'([ \t]*)(\{ label: "Real stories", href: "/learn/real-stories" \},)', src)
            if m:
                src = src.replace(m.group(2), m.group(2) + "\n" + m.group(1) + '{ label: "Glossary", href: "/learn/glossary" },', 1)
                print("   added Glossary to Learn")

        n = src.count('label: "Employers"')
        if n:
            src = src.replace('label: "Employers"', 'label: "Workplace"')
            print("   renamed Employers to Workplace (" + str(n) + " places)")

        if src != original:
            header.with_suffix(".tsx.bak-before-symptoms-learn-workplace").write_text(original, encoding="utf-8")
            header.write_text(src, encoding="utf-8")

    print("")
    print("Check it compiles:")
    print("   npx tsc --noEmit 2>&1 | grep -E 'blog|learn|workplace|cart'")
    print("")
    print("If any page 404s, restart the dev server: Ctrl+C, then rm -rf .next && pnpm dev")
    print("")
    print("Then open:")
    for d in PAGES:
        print("   http://localhost:3000/" + d.replace("app/", ""))


if __name__ == "__main__":
    main()
